SELECT game_slug FROM games.game_registry WHERE game_slug IN ('scratch','summon','slot') ORDER BY game_slug FOR UPDATE;
ALTER TABLE games.slot_results DROP CONSTRAINT slot_results_reel_strip_version_check;
ALTER TABLE games.slot_results ADD CONSTRAINT slot_results_reel_strip_version_check CHECK (reel_strip_version IN ('slot-strips-v1','slot-strips-v2'));
